/* Village reporting presentation; all accepted counts are owned by the server. */
(()=>{
  'use strict';
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const modes={increment:'新增一批',snapshot:'当前待转移总数',correction:'更正历史批次'};
  const statuses={pending:'待指挥台核实',accepted:'已核实',rejected:'未采纳',superseded:'已更正归档'};
  const groups={unknown:'尚未确认',splittable:'独立人员，可按容量分组',together:'同行一组，不可拆分'};
  const clock=x=>x?new Date(x).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';
  const selected=(a,b)=>a===b?'selected':'';
  const village=(d,id)=>d.villages?.find(v=>v.id===id);
  const point=(d,p)=>village(d,p.villageId)?.pickups.find(x=>x.id===p.pickupId)?.name||'集合点待补充';
  function targets(d,id){return (d.villageReports||[]).filter(r=>r.villageId===id&&r.status==='accepted'&&r.mode!=='snapshot'&&!r.supersededBy&&!(d.villageReports||[]).some(x=>x.mode==='correction'&&x.status==='pending'&&x.targetId===r.id)&&(r.householdIds||[]).every(h=>d.stage[h]==='waiting'));}
  function duplicate(d,p){return p?.mode==='increment'?(d.villageReports||[]).find(r=>['pending','accepted'].includes(r.status)&&r.mode==='increment'&&r.villageId===p.villageId&&(r.pickupId||'')===(p.pickupId||'')&&r.people===Number(p.people)&&Date.now()-Date.parse(r.createdAt)<30*60*1000):null;}
  function fields(d,p,prefix,editable=true){
    const bind=k=>editable?`data-vdraft="${k}"`:'';
    return `<div class="form-grid village-facts"><div><label for="${prefix}-people">${p.mode==='snapshot'?'当前仍待转移':p.mode==='correction'?'该批次更正为':'本批新增'}人数（总人数）</label><input id="${prefix}-people" ${bind('people')} ${!editable?'readonly class="village-review-readonly"':''} type="number" min="${p.mode==='increment'?1:0}" max="500" step="1" value="${esc(p.people)}" required></div><div><label for="${prefix}-pickup">集合点</label><select id="${prefix}-pickup" ${bind('pickupId')}><option value="">尚未明确，稍后补充</option>${(village(d,p.villageId)?.pickups||[]).map(x=>`<option value="${x.id}" ${selected(p.pickupId,x.id)}>${esc(x.name)}</option>`).join('')}</select></div><div><label for="${prefix}-assistance">其中需协助人数</label><input id="${prefix}-assistance" ${bind('assistancePeople')} type="number" min="0" max="500" step="1" placeholder="未确认请留空" value="${esc(p.assistancePeople)}"></div><div><label for="${prefix}-wheelchair">协助人员中需轮椅位人数</label><input id="${prefix}-wheelchair" ${bind('wheelchairPeople')} type="number" min="0" max="500" step="1" placeholder="未确认请留空" value="${esc(p.wheelchairPeople)}"></div><div class="full"><label for="${prefix}-group">同行关系</label><select id="${prefix}-group" ${bind('groupPolicy')}>${Object.entries(groups).map(([id,label])=>`<option value="${id}" ${selected(p.groupPolicy,id)}>${label}</option>`).join('')}</select></div></div>`;
  }
  function composer(state,ui,h){const d=state.data,v=ui.form,active=ui.voiceActive;
    return `<section class="panel village-composer" id="village-composer"><div class="assistant-heading"><span class="ai-emblem">声</span><div><span class="eyebrow">VILLAGE / REPORT</span><h2>村级人数上报</h2></div>${h.badge('语音 → 确认卡','teal')}</div><div class="panel-body"><div class="village-steps"><span><b>1</b>选择村庄</span><span><b>2</b>说出情况</span><span><b>3</b>核对后提交</span></div><div class="form-grid village-context"><div><label for="village-id">所属村庄 · 演示乡镇</label><select id="village-id" ${active?'disabled':''}><option value="">请选择上报村庄</option>${(d.villages||[]).map(x=>`<option value="${x.id}" ${selected(v.villageId,x.id)}>${esc(x.name)}</option>`).join('')}</select></div><div><label for="village-mode">这次报的是什么人数？</label><select id="village-mode" ${active?'disabled':''}>${Object.entries(modes).map(([id,label])=>`<option value="${id}" ${selected(v.mode,id)}>${label}</option>`).join('')}</select></div><div class="full"><label for="village-pickup">已知集合点（可选）</label><select id="village-pickup" ${active?'disabled':''}><option value="">暂不清楚，先报人数</option>${(village(d,v.villageId)?.pickups||[]).map(x=>`<option value="${x.id}" ${selected(v.pickupId,x.id)}>${esc(x.name)}</option>`).join('')}</select></div>${v.mode==='correction'?`<div class="full"><label for="village-target">更正哪一条已核实批次？</label><select id="village-target"><option value="">请选择原批次</option>${targets(d,v.villageId).map(r=>`<option value="${r.id}" ${selected(v.targetId,r.id)}>${r.id} · ${r.people} 人 · ${point(d,r)}</option>`).join('')}</select><small>已上车或已到达的批次不可在这里改人数。</small></div>`:''}${v.mode==='snapshot'?`<div class="full"><label for="village-observed">人数清点时间</label><input id="village-observed" type="datetime-local" value="${esc(v.observedAt)}"><small>记录本村此时仍待转移的总数，不与已有批次相加。</small></div>`:''}</div><div class="village-voice-box"><label for="village-utterance">说出或输入这次上报内容</label><textarea id="village-utterance" maxlength="2000" ${active?'readonly':''} placeholder="例如：新增20人，其中3人需要协助，包含1名轮椅人员。都是独立人员，可以分组。">${esc(v.text)}</textarea>${h.voiceHTML('village')}<div class="actions">${h.btn('整理为确认卡','village-prepare',active?'disabled':'','primary')}${h.btn('填入示例','village-example',active?'disabled':'','quiet')}${h.btn('直接填写确认卡','village-manual',active?'disabled':'','quiet')}</div></div><p class="assistant-mode">浏览器识别语音，本地规则整理人数；DeepSeek 待接入。村庄与集合点均为合成演示，不代表真实行政村或真实接送位置。</p></div></section>`;
  }
  function preview(state,ui,h){const prepared=ui.prepared,p=prepared?.proposal?.payload,d=state.data,stale=prepared&&(prepared.session!==state.session||prepared.revision!==d.revision),dup=duplicate(d,p);
    let body=`<div class="field-preview-empty"><span>↗</span><strong>把一句话变成一张上报单</strong><p>整理后在这里修改人数、集合点和协助需求。核对无误，点击一次即可提交到指挥台。</p></div>`;
    if(prepared&&!p)body=`<div class="notice warn"><strong>还需要补充信息</strong>${(prepared.questions||[]).map(x=>`<p>${esc(x)}</p>`).join('')}</div><p class="boundary">请补全原话或切换“直接填写确认卡”。</p>`;
    if(p)body=`<div class="close-row"><strong>${esc(village(d,p.villageId)?.name||'请先选择村庄')}</strong>${h.badge(modes[p.mode])}</div>${p.targetId?`<p class="boundary">更正 ${esc(p.targetId)}：经指挥台核实后替换原批次，保留历史。</p>`:''}${p.mode==='snapshot'?`<div class="notice">清点时间：${clock(p.observedAt)}。这是待转移总数观测，不自动增减批次。</div>`:''}${fields(d,p,'vdraft')}<p class="boundary">协助人数包含轮椅人数，均已包含在总人数里，不重复相加。未知需求请留空。</p><div class="village-draft-state" id="village-draft-state">${draftState(d,p,h)}</div><label for="village-reporter">本次上报人</label><input id="village-reporter" maxlength="40" value="${esc(p.reporter)}"><details class="village-original"><summary>查看原话与整理依据</summary><blockquote>${esc(p.text||'手动填写的结构化上报')}</blockquote>${(prepared.evidence||[]).map(x=>`<p>${esc(x)}</p>`).join('')}${(prepared.warnings||[]).map(x=>`<p>${esc(x)}</p>`).join('')}</details>${stale?`<div class="notice warn">现场记录已更新。请核对最新台账，再更新这张确认卡的依据。${h.btn('保留填写，更新依据','village-refresh','','small')}</div>`:''}<div id="village-duplicate">${duplicateHTML(d,p,h)}</div><div class="actions village-submit-row">${h.btn(submitLabel(p),'village-submit',stale||ui.voiceActive||!ui.connected||dup&&!p.duplicateAcknowledged?'disabled':'','primary')}${h.btn('清空本次','village-clear',ui.voiceActive?'disabled':'','quiet')}</div><p class="boundary">${p.mode==='snapshot'?'点击确认后等待指挥台核实，只保存清点观测，不累加到转移对象。':p.mode==='correction'?'核实后替换原批次人数；核实前仍按原批次计数。':'点击确认后进入“待核实”；指挥台核实后才计入转移对象。'}</p>`;
    return `<section class="panel village-preview" id="village-preview">${h.head('核对本次上报','字段可编辑 · 人工确认后即时同步',h.badge(p?'待您确认':'等待整理',p?'teal':'gray'))}<div class="panel-body">${body}</div></section>${ui.receipt?`<div class="notice field-receipt" role="status"><strong>✓ ${esc(ui.receipt)}</strong><p>已进入村级台账，指挥台处理结果会同步显示在下方。</p></div>`:''}`;
  }
  function submitLabel(p){return p.mode==='snapshot'?'确认提交当前总数观测':p.mode==='correction'?`确认提交更正为 ${p.people||0} 人`:`确认上报新增 ${p.people||0} 人 ↗`;}
  function draftState(d,p,h){const missing=[!p.pickupId?'集合点':null,p.assistancePeople===null||p.assistancePeople===''?'协助人数':null,p.wheelchairPeople===null||p.wheelchairPeople===''?'轮椅人数':null,p.groupPolicy==='unknown'?'同行关系':null].filter(Boolean);return p.mode==='snapshot'?h.badge('只记录观测，不自动计算新增量','gray'):missing.length?`<p class="notice warn">可先上报；核实后还需补充${missing.join('、')}，暂不生成接送路线。</p>`:`<p class="notice">信息已齐：核实后${p.groupPolicy==='together'?'按一个不可拆分组进入调度，车辆不足则待协调。':'按最多 4 人的接送组进入调度，原批次总数保留。'}</p>`;}
  function duplicateHTML(d,p,h){const dup=duplicate(d,p);return dup?`<div class="notice warn"><strong>疑似重复：${dup.id} 也报了 ${dup.people} 人</strong><p>同村、同集合点在最近 30 分钟内有相同新增人数。请核实是否属于另一批人员。</p>${p.duplicateAcknowledged?h.badge('已声明属于另一批','teal'):h.btn('确认是另一批，继续核对','village-duplicate','','small')}</div>`:'';}
  function ledger(state,ui,h){const d=state.data,rows=state.villageLedger||[],pending=(d.villageReports||[]).filter(r=>r.status==='pending').length;
    return `<section class="panel village-ledger" id="village-ledger">${h.head('村级转移台账','待核实新增与已核实待接分开统计',h.badge(pending+' 条待核实',pending?'red':'teal'))}<div class="village-ledger-grid">${rows.map(r=>`<article><div class="close-row"><strong>${esc(r.villageName)}</strong>${h.badge('演示','gray')}</div><div class="village-number"><b>${r.waiting}</b><span>人已核实待接</span></div><div class="village-small-metrics"><span>待核实新增 <b>${r.pendingPeople}</b></span><span>待补信息 <b>${r.unplannedPeople}</b></span><span>已上车 <b>${r.boarded}</b></span><span>到达待核验 <b>${r.arrived}</b></span><span>已核验 <b>${r.verified}</b></span><span>待审更正 <b>${r.pendingCorrections||0} 条</b></span></div>${r.latestSnapshot?`<p class="village-observation">最近清点：${r.latestSnapshot.people} 人待转移 · ${clock(r.latestSnapshot.observedAt)}<br>仅作对账观测，请核对清点时间与已核实批次。</p>`:''}</article>`).join('')}</div><p class="boundary village-ledger-foot">“待补信息”包含在“已核实待接”中。当前总数观测和待审更正不直接累加到人数。</p></section>`;
  }
  function reports(state,ui,h){const d=state.data,all=d.villageReports||[],chosen=ui.filter||'',rows=all.filter(r=>!chosen||r.villageId===chosen),active=rows.filter(r=>r.status==='pending'||r.status==='accepted'&&r.needsInfo),done=rows.filter(r=>!active.includes(r));
    function card(r){const eligible=targets(d,r.villageId).some(x=>x.id===r.id);return `<article class="village-report-card" data-village-report="${r.id}"><div class="close-row"><strong>${esc(r.id)} · ${esc(village(d,r.villageId)?.name)}</strong>${h.badge(statuses[r.status]+(r.status==='accepted'&&r.needsInfo?' · 待补信息':''),r.status==='pending'?'red':r.status==='superseded'?'gray':'teal')}</div><p><b>${esc(modes[r.mode])} ${r.people} 人</b> · ${esc(point(d,r))}</p><p class="boundary">需协助 ${r.assistancePeople??'未确认'} 人（其中轮椅 ${r.wheelchairPeople??'未确认'} 人） · ${esc(groups[r.groupPolicy])}${r.targetId?' · 原批次 '+esc(r.targetId):''}${r.householdIds?.length?' · 已形成 '+r.householdIds.length+' 个接送组':''}</p><details><summary>原话、时间与处理说明</summary><p>${esc(r.text)}</p><small>${esc(r.reporter)} · ${clock(r.createdAt)}</small>${r.note?`<p>核实说明：${esc(r.note)}</p>`:''}${r.completionNote?`<p>补齐依据：${esc(r.completionNote)}</p>`:''}${r.possibleDuplicateOf?`<p>上报时已声明为另一批人员，核对记录 ${esc(r.possibleDuplicateOf)}。</p>`:''}${r.supersededBy?`<p>替换批次：${esc(r.supersededBy)}</p>`:''}</details><div class="actions">${ui.view==='command'&&r.status==='pending'?h.btn('核实这条上报','village-review',`data-id="${r.id}"`,'primary small'):''}${ui.view==='command'&&r.status==='accepted'&&r.needsInfo?h.btn('补齐信息并生成接送组','village-complete',`data-id="${r.id}"`,'primary small'):''}${ui.view==='field'&&eligible?h.btn('更正这批人数','village-correct',`data-id="${r.id}"`,'small'):''}</div></article>`;}
    return `<section class="panel" id="village-reports">${h.head(ui.view==='command'?'村级上报待办':'村级上报与处理结果','所有记录可在两端查看',h.badge(all.length+' 条'))}<div class="panel-body village-filter"><label for="village-filter">筛选村庄</label><select id="village-filter"><option value="">全部演示村</option>${(d.villages||[]).map(x=>`<option value="${x.id}" ${selected(chosen,x.id)}>${esc(x.name)}</option>`).join('')}</select></div>${active.map(card).join('')}${done.length?`<details class="village-history" ${!active.length?'open':''}><summary>已处理记录（${done.length} 条）</summary>${done.map(card).join('')}</details>`:''}${!rows.length?'<p class="empty">暂无村级上报。选择村庄，说出新增人数即可开始。</p>':''}</section>`;
  }
  function review(state,id,kind){const r=state.data.villageReports.find(x=>x.id===id);if(!r)throw new Error('记录已变化，请刷新');return `<h2>${kind==='village-complete'?'补齐接送信息':'核实村级上报'} ${esc(r.id)}</h2><p>${esc(village(state.data,r.villageId)?.name)} · ${esc(modes[r.mode])} ${r.people} 人</p><div class="notice">${esc(r.text)}</div>${kind==='village-review'?'<label for="village-decision">核实结论</label><select id="village-decision"><option value="accept">核实采纳</option><option value="reject">不采纳</option></select>':''}${r.mode==='snapshot'?'<p class="boundary">采纳后记录清点观测，不自动增减已核实批次。</p>':fields(state.data,r,'vreview',false)+'<p class="boundary">人数更正请由现场提交更正批次。本窗口可补齐集合点、协助需求和同行关系。核实时允许留空先采纳；“补齐信息”操作需要全部填写，才能生成接送组。</p>'}<label for="village-note">${kind==='village-complete'?'补全依据':'核实说明'}</label><textarea id="village-note" maxlength="300" required placeholder="记录与谁核对、核对结果"></textarea><button type="submit" class="primary">${kind==='village-complete'?'保存并生成接送组':'保存核实结果'}</button>`;}
  window.JiaoyingVillageUI={composer,preview,ledger,reports,review,targets,duplicate,duplicateHTML,draftState,submitLabel};
})();
